 select * from inventory;
 
 
 -- 1. Top 10 best-selling products
select b.product_name, sum(a.quantity) as units_sold,
sum(a.quantity * a.unit_price - a.discount) as revenue
from order_items a
join products b on a.product_id = b.product_id
group by b.product_id order by units_sold desc limit 10;

-- 2. Monthly revenue trend
select date_format(a.order_date,'%Y-%m') as month,
sum(b.quantity * b.unit_price - b.discount) as revenue
from orders as a JOIN order_items as b on a.order_id = b.order_id
where a.order_status in ('Delivered','Shipped')
GROUP BY month ORDER BY month;

-- 3. Low-stock alerts (below recorder_level)
select i.branch_id, p.product_name, i.stock_quantity, p.recorder_level
from inventory i join products p on i.product_id = p.product_id
where i.stock_quantity < p.recorder_level;

-- 4. List all customers from Mumbai sorted alphabetically by name.
select customer_id,customer_name,city from customers where city='mumbai' order by customer_name asc;

-- 5. Show all products whose unit_price is greater than 10,000, ordered by price descending
select * from products where unit_price > 10000 order by unit_price desc;

-- 6.  Count the total number of orders in the system.
select count(order_id) as total_orders from orders;

-- 7. Display all categories with their names.
select * from categories;

-- 8. Find all employees earning more than 50,000 per month.
select * from employees where salary > 50000;

-- 9. List all products belonging to the Electronics category.
select a.product_id,a.product_name,b.category_id,b.category_name 
from products as a 
join categories as b on a.category_id=b.category_id
where b.category_name='Electronics';

-- 10. Show all orders with status 'Delivered' placed in 2024.
select * from orders where order_status='Delivered' and year(order_date) =2024;

-- 11. List all branches located in Maharashtra.
select * from branches where state='Maharashtra';

-- 12. Find customers who registered in 2023
select * from customers where year(registration_date)=2023;

-- 13.  List the distinct payment methods used by customers
select distinct payment_method from payments;

-- 14. Calculate total revenue per order (quantity × unit_price − discount).
select order_id,sum(quantity * unit_price - discount) as total_revenue  from order_items 
group by order_id 
order by order_id asc;

-- 15. Find the Top 10 best-selling products by total quantity sold.
select sum(a.quantity) as total_quantity,b.product_id,b.product_name 
from order_items as a
join products as b on a.product_id=b.product_id 
group by a.product_id , b.product_name 
order by total_quantity desc limit 10;

-- 16. Show the number of orders placed by each customer, sorted descending.
select count(a.order_id) as order_count,a.customer_id,b.customer_name
  from orders as a
  join customers as b on a.customer_id=b.customer_id 
  group by a.customer_id order by order_count desc;
  
  -- 17.  Calculate total revenue generated by each branch.
select b.branch_id,b.branch_name,
coalesce(sum(oi.quantity * oi.unit_price - oi.discount), 0) as total_revenue
from branches b
left join orders o on o.branch_id = b.branch_id
left join order_items oi on oi.order_id = o.order_id
group by b.branch_id, b.branch_name
order by total_revenue desc;

-- 18. Find the average order value per customer.
with order_revenue as (
    select order_id,
           sum(quantity * unit_price - discount) as total
    from order_items
    group by order_id																																
)																			
select c.customer_id,
       c.customer_name,
       round(avg(orv.total)) as avg_order_value
from customers c
join orders o on o.customer_id = c.customer_id
join order_revenue as orv on orv.order_id   = o.order_id
group by c.customer_id, c.customer_name
order by avg_order_value desc;
 
 -- 19. List products where stock_quantity is below recorder_level (low-stock alerts).
SELECT p.product_id,
       p.product_name,
       i.branch_id,
       i.stock_quantity,
       p.recorder_level,
       (p.recorder_level - i.stock_quantity) AS shortage
FROM inventory as i
JOIN products as p ON p.product_id = i.product_id
WHERE i.stock_quantity < p.recorder_level;

-- 20. Calculate total sales revenue per category.
select round(sum(oi.quantity * oi.unit_price - oi.discount))as total_sales,g.category_id,g.category_name
from products as p
join categories as g on p.category_id=g.category_id
join order_items as oi on oi.product_id=p.product_id
group by g.category_id,g.category_name
order by total_sales  desc;

-- 21. Show each employee's total sales amount (via orders they handled).
select e.employee_id,employee_name,e.job_role,round(sum(oi.quantity * oi.unit_price - oi.discount)) as total_sales_amount
from employees as e
left join orders as o on o.employee_id=e.employee_id
join order_items as oi on oi.order_id=o.order_id
group by e.employee_id ,e.employee_name,e.job_role
order by total_sales_amount desc;

 -- 22. Display the monthly sales trend (revenue by month) for 2024.
select date_format(o.order_date,'%y-%m') as month,
count(distinct o.order_id) as total_orders,
round(sum(oi.quantity * oi.unit_price - oi.discount)) as total_revenue
from orders as o
join order_items as oi on oi.order_id=o.order_id
where year(order_date) = 2024
group by date_format(o.order_date,'%y-%m')
order by month;

 -- 23. Find the Top 10 customers by lifetime value (total spend).
 select c.customer_id,c.customer_name,c.city,c.state, count(distinct o.order_id) as total_ordes,
 round(sum(oi.quantity * oi.unit_price - oi.discount)) as life_time_value
 from customers as c 
 join orders as o on o.customer_id=c.customer_id
 join order_items as oi on oi.order_id=o.order_id
 group by c.customer_id,c.customer_name,c.city,c.state
 order by life_time_value desc limit 10;
 
 -- 24. Show the distribution of payment_status (count of each status).
 select payment_status, count(*) as status_count
 from payments
 group by payment_status
 order by status_count desc;
 
 -- 25. Count how many orders were placed at each branch.
 select count(o.order_id) as order_count,o.branch_id,b.branch_name 
 from orders as o
 join branches as b on b.branch_id=o.branch_id
 group by o.branch_id,b.branch_name
 order by order_count asc;
 
 -- 26. Find products that have never been ordered.
select p.product_id,p.product_name
from products  as p
left join order_items as oi on oi.product_id=p.product_id
where oi.product_id is null;

-- 27. List each supplier with the number of products they supply.
select s.supplier_id,s.supplier_name,count(p.product_id) as product_count
from suppliers as s
left join products as p on p.supplier_id=s.supplier_id
group by supplier_id,supplier_name
order by product_count desc;

-- 28. Calculate branch-wise inventory value (stock_quantity × cost_price).
select b.branch_id,b.branch_name,b.city,sum(i.stock_quantity)as total, sum(i.stock_quantity * p.cost_price) as inventry_value
from branches as b 
left join inventory as i on i.branch_id=b.branch_id
left join products as p on p.product_id=i.product_id
group by b.branch_id,b.branch_name,b.city
order by inventry_value desc;

-- 29. Rank customers by total spend using a window function (RANK()).
with customer_spend as
( select c.customer_id,c.customer_name,
sum(oi.quantity * oi.unit_price - oi.discount) as total_spend
from customers as c
join orders as o on o.customer_id=c.customer_id
join order_items as oi on oi.order_id=o.order_id
group by c.customer_id,c.customer_name)
select customer_id,customer_name,
round(total_spend) as total_spend,
rank()over(order by total_spend desc) as spend_rank	
from customer_spend
order by spend_rank;

-- 30. Calculate the running total of monthly revenue across 2024.
with monthly_revenue as (
    select date_format(o.order_date, '%Y-%m') as month,
           sum(oi.quantity * oi.unit_price - oi.discount) as revenue
    from orders as o
    join order_items oi ON oi.order_id = o.order_id
    where year(o.order_date) = 2024
    group by  date_format(o.order_date, '%Y-%m')
)
select month,
       round(revenue, 2) as monthly_revenue,
       ROUND(SUM(revenue) over (ORDER BY month), 2) as running_total
from monthly_revenue
order by month;

-- 31. Show month-over-month revenue growth rate (percentage).
with monthly_revenue as (
    select date_format(o.order_date, '%Y-%m') as month,
           sum(oi.quantity * oi.unit_price - oi.discount) as revenue
    from orders o
    join order_items oi on oi.order_id = o.order_id
    where year(o.order_date) = 2024
    group by date_format(o.order_date, '%Y-%m')
)
select month,
       round(revenue, 2) as monthly_revenue,
       round(lag(revenue) over (order by month), 2) as prev_month_revenue,
       round(
           100 * (revenue - lag(revenue) over (order by month))
               / nullif(lag(revenue) over (order by month), 0), 2) as mom_growth_pct
from monthly_revenue
order by month;

-- 32. Rank categories by total revenue and show their rank + share %.
with category_revenue as (
    select c.category_id,
           c.category_name,
           sum(oi.quantity * oi.unit_price - oi.discount) as revenue
    from categories c
    join products p     on p.category_id = c.category_id
    join order_items oi on oi.product_id = p.product_id
    group by c.category_id, c.category_name
)
select category_id,
       category_name,
       round(revenue, 2) as total_revenue,
       rank() over(order by revenue desc) as revenue_rank,
       round(100 * revenue / sum(revenue) over (), 2) as share_pct
from category_revenue
order by revenue_rank;

-- 33. Find customers who placed orders in consecutive months.
with customer_months as (
    select distinct
           c.customer_id,
           c.customer_name,
           date_format(o.order_date, '%Y-%m') as order_month
    from customers as c
    Join orders as o ON o.customer_id = c.customer_id
),
with_prev as (
    select customer_id,
           customer_name,
           order_month,
           lag(order_month) over (partition  by customer_id order by order_month) as prev_month
    from customer_months
)
select distinct
       customer_id,
       customer_name,
       prev_month as from_month,
       order_month as to_month,
       timestampdiff(month, str_to_date(concat(prev_month,'-01'), '%Y-%m-%d'),
                            str_to_date(concat(order_month,'-01'), '%Y-%m-%d')) as month_gap
from with_prev
where prev_month is not null
  and timestampdiff(month, str_to_date(concat(prev_month,'-01'), '%Y-%m-%d'),
                           str_to_date(concat(order_month,'-01'), '%Y-%m-%d')) = 1
order by customer_id, from_month;

-- 34. Identify products with the highest profit margin (unit_price − cost_price) and their total profit.
select p.product_id,
       p.product_name,
       p.unit_price,
       p.cost_price,
       (p.unit_price - p.cost_price) AS unit_margin,
       coalesce(sum(oi.quantity),0)as total_sold,
       round(coalesce(sum(oi.quantity*(p.unit_price - p.cost_price)),0),2) as total_profit
       from products as p
       left join order_items as oi on oi.product_id=p.product_id
       group by p.product_id,p.product_name,p.unit_price,p.cost_price
       order by unit_margin desc limit 10;
       
-- 35. Rank employees by sales within each branch (partitioned ranking).
with employee_sales as (
    select e.employee_id,
           e.employee_name,
           e.branch_id,
           e.job_role,
           coalesce(sum(oi.quantity * oi.unit_price - oi.discount), 0) as total_sales
    from employees as e
    left join orders as o       ON o.employee_id = e.employee_id
    left join order_items as oi on oi.order_id   = o.order_id
    group by e.employee_id, e.employee_name, e.branch_id, e.job_role
)
select es.branch_id,
       b.branch_name,
       es.employee_id,
       es.employee_name,
       es.job_role,
       round(es.total_sales, 2) as total_sales,
       rank() over (partition by es.branch_id order by es.total_sales desc) as rank_in_branch
from employee_sales es
join branches b on b.branch_id = es.branch_id
order by es.branch_id, rank_in_branch;

 -- 36. Perform cohort analysis — group customers by registration year and show their order counts.
 select year(c.registration_date) as cohort_year,
       count(distinct c.customer_id) as total_customers,
       count(o.order_id) as total_orders,
       round(count(o.order_id) / count(distinct c.customer_id), 2) as avg_orders_per_customer
from customers c
left join orders as o on o.customer_id = c.customer_id
group by year(c.registration_date)
order by cohort_year asc;

-- 37. Identify slow-moving inventory (products in inventory with zero sales in last 6 months).
set @max_date = (select max(order_date) from orders);
select p.product_id,
       p.product_name,
       c.category_name,
       SUM(i.stock_quantity) as total_stock,
       group_concat(distinct i.branch_id order by i.branch_id) as branches_with_stock
from products as p
join categories as c   on c.category_id = p.category_id
join inventory as i    on i.product_id  = p.product_id
where not exists (
    select 1
    from order_items oi
    join orders as o on o.order_id = oi.order_id
    WHERE oi.product_id = p.product_id
      and o.order_date >= date_sub(@max_date, interval 6 month)
      and o.order_status in ('Delivered','Shipped','Pending')
)
group by p.product_id, p.product_name, c.category_name
order by total_stock desc;


-- 38. Find the top customer per branch by total spend (one row per branch).
with branch_customer_spend as (
    select o.branch_id,
           c.customer_id,
           c.customer_name,
           sum(oi.quantity * oi.unit_price - oi.discount) as total_spend
    from orders as o
    join customers as c    on c.customer_id = o.customer_id
    join order_items as oi on oi.order_id   = o.order_id
    group by o.branch_id, c.customer_id, c.customer_name
),
ranked as (
    select branch_id,
           customer_id,
           customer_name,
           total_spend,
           row_number() over (partition by branch_id
                              order by total_spend desc) as rn
    from branch_customer_spend
)
select r.branch_id,
       b.branch_name,
       r.customer_id,
       r.customer_name,
       round(r.total_spend, 2) as total_spend
from ranked as r
join branches as b on b.branch_id = r.branch_id
where r.rn = 1
order by r.branch_id;